  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "The doctor avoided a single-cause interpretation and integrated infection, kidney, residual urine, and prostate findings into the plan.",
          "quote": "前列腺约45ml增大"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor used new formal results to distinguish neurogenic bladder, obstruction, infection, and renal-risk possibilities, then changed the plan accordingly rather than relying on impressions or one reassuring result.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00196",
          "explanation": "The doctor corrected the patient's expectation that the first dose should immediately improve the urine stream.",
          "quote": "不会立刻就让尿线马上明显变粗"
        }
      ],
      "completion": "partial",
      "explanation": "The doctor did correct a patient misunderstanding about immediate medication effect and observation thresholds, but did not fully address the case-defined misunderstandings about first-stage sacral neuromodulation, research device follow-up, or formal preoperative clearance beyond minimum safety.",
      "ho_id": "HO2",
      "meaningful_trajectory_impact": false,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00060",
          "explanation": "The doctor repaired part of the document/result responsibility gap by directing the patient to formal report pages and medication reconciliation.",
          "quote": "正式报告结果页"
        }
      ],
      "completion": "partial",
      "explanation": "The doctor repaired some practical gaps around formal reports, medication labels, and follow-up contacts, but did not complete the case-specific insulin-day-of-procedure or research-product follow-up responsibility-chain repairs.",
      "ho_id": "HO3",
      "meaningful_trajectory_impact": false,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00109",
          "explanation": "After residual urine and prostate findings emerged, the doctor shifted priority from procedure planning to urgent local urologic assessment and pausing the trial.",
          "quote": "先不要急着做骶神经电极试验"
        }
      ],
      "completion": "complete",
      "explanation": "The doctor dynamically reprioritized the episode after the abnormal residual urine result, directing same-day urology review and deferring the sacral neuromodulation trial until the retention/obstruction question was addressed.",
      "ho_id": "HO4",
      "meaningful_trajectory_impact": true,
      "triggered": true
    }
  ],
